+// reportLatency estimates the time spent since the last update of the resource object and records it to the latency metric
+func reportLatency(ctx *context.Context, resourceObj interface{}, metricsReporter *metrics.LatencyReporter, resourceKind, resourceName string) {
+	if latestUpdateTime, err := customresourceutil.RetrieveLatestUpdateTime(resourceObj); err == nil {
+		if err := metricsReporter.ReportLatency(*ctx, time.Now().Sub(*latestUpdateTime), resourceKind, resourceName); err != nil {
+			logging.FromContext(*ctx).Error("Failed to report latency", zap.Error(err))
+		}
+	} else {
+		logging.FromContext(*ctx).Error("Failed to retrieve the resource update time", zap.Error(err))
+	}
+}

File: pkg/metrics/brokercell_delay_reporter.go  Lines: 66-79
@@ -0,0 +66,14 @@
+// ReportLatency records the value to the latency metric
+func (r *LatencyReporter) ReportLatency(ctx context.Context, duration time.Duration, resourceKind, resourceName string) error {
+	tag, err := tag.New(
+		ctx,
+		tag.Insert(ResourceKindKey, resourceKind),
+		tag.Insert(ResourceNameKey, resourceName),
+	)
+	if err != nil {
+		return fmt.Errorf("failed to create metrics tag: %v", err)
+	}
+	durationMetricValue := r.durationInMsecM.M(float64(duration / time.Millisecond))
+	metrics.Record(tag, durationMetricValue)
+	return nil
+}

