+// GetOutPutsMapping returns a mapping of temporary output(plz-out/tmp/) to real output(plz-out/bin/)
+// Check if each output has the same name as the package, this avoids the name conflict issue
+func (target *BuildTarget) GetOutPutsMapping(parseOutputs []string) map[string]string {
+	var outputMapping = make(map[string]string, len(parseOutputs))
+	var tmpOutput []string
+
+	for _, out := range parseOutputs {
+		if out == target.Label.PackageName {
+			outputMapping[fmt.Sprintf(tmpOutputFormat, out)] = out
+			tmpOutput = append(tmpOutput, fmt.Sprintf(tmpOutputFormat, out))
+		} else {
+			outputMapping[out] = out
+			tmpOutput = append(tmpOutput, out)
+		}
+	}
+
+	return outputMapping
+}

File: src/build/build_step.go  Lines: 404-415
// RemoveOutputs removes all generated outputs for a rule.
func RemoveOutputs(target *core.BuildTarget) error {
	for _, output := range target.Outputs() {
		out := path.Join(target.OutDir(), output)
		if err := os.RemoveAll(out); err != nil {
			return err
		} else if err := fs.EnsureDir(out); err != nil {
			return err
		}
	}
	return nil
}

File: src/build/build_step.go  Lines: 282-303
// Prepares the output directories for a target
func prepareDirectories(target *core.BuildTarget) error {
	if err := prepareDirectory(target.TmpDir(), true); err != nil {
		return err
	}
	if err := prepareDirectory(target.OutDir(), false); err != nil {
		return err
	}
	// Nicety for the build rules: create any directories that it's
	// declared it'll create files in.
	for _, out := range target.Outputs() {
		if dir := path.Dir(out); dir != "." {
			outPath := path.Join(target.TmpDir(), dir)
			if !core.PathExists(outPath) {
				if err := os.MkdirAll(outPath, core.DirPermissions); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

