func fromJSONHex(b []byte) ([]byte, error) {
	var x string
	if err := json.Unmarshal(b, &x); err != nil {
		return nil, err
	}
	return hex.DecodeString(x)
}

func fromMsgPackHex(b []byte) ([]byte, error) {
	var x string
	if err := msgpack.Unmarshal(b, &x); err != nil {
		return nil, err
	}
	return hex.DecodeString(x)
}

