		p, err := c.Receive()
		if ret := ErrMsg(&p, err); ret != nil {
			errCh <- ret
		} else {
			msgCh <- p
		}
	}()

	select {
	case resp := <-msgCh:
		return &resp, nil
	case err := <-errCh:
		return nil, err
	case <-time.After(timeoutResponse):
		return nil, errors.New("Timeout on sending message")
	}
}

