File: src/test/test_step.go  Lines: 39-60
func Test(tid int, state *core.BuildState, label core.BuildLabel, remote bool, run int) {
	target := state.Graph.TargetOrDie(label)

	// Defer this so that no matter what happens in this test run, we always call target.CompleteRun
	defer func() {
		runsAllCompleted := target.CompleteRun(state)
		if runsAllCompleted && state.Config.Test.Upload != "" {
			if numUploadFailures < maxUploadFailures {
				if err := uploadResults(target, state.Config.Test.Upload.String(), state.Config.Test.UploadGzipped, state.Config.Test.StoreTestOutputOnSuccess); err != nil {
					if failures := atomic.AddInt64(&numUploadFailures, 1); failures < maxUploadFailures {
						log.Warning("%s", err)
					} else if failures == maxUploadFailures {
						log.Error("Failed to upload test results %d times, giving up", maxUploadFailures)
					}
				}
			}
		}
	}()

	state.LogBuildResult(tid, target, core.TargetTesting, "Testing...")
	test(tid, state.ForTarget(target), label, target, remote, run)
}

File: src/build/build_step.go  Lines: 44-66
func Build(tid int, state *core.BuildState, label core.BuildLabel, remote bool) {
	target := state.Graph.TargetOrDie(label)
	state = state.ForTarget(target)
	target.SetState(core.Building)
	if err := buildTarget(tid, state, target, remote); err != nil {
		if errors.Is(err, errStop) {
			target.SetState(core.Stopped)
			state.LogBuildResult(tid, target, core.TargetBuildStopped, "Build stopped")
			return
		}
		state.LogBuildError(tid, label, core.TargetBuildFailed, err, "Build failed: %s", err)
		if err := RemoveOutputs(target); err != nil {
			log.Errorf("Failed to remove outputs for %s: %s", target.Label, err)
		}
		target.SetState(core.Failed)
		return
	}
	// Mark the target as having finished building.
	target.FinishBuild()
	if target.IsTest && state.NeedTests && state.IsOriginalTarget(target) {
		state.AddPendingTest(target)
	}
}

