File: internal/pipe/nfpm/nfpm.go  Lines: 93-115
func create(ctx *context.Context, format, arch string, binaries []artifact.Artifact) error {
	overrided, err := mergeOverrides(ctx, format)
	if err != nil {
		return err
	}
	name, err := tmpl.New(ctx).
		WithArtifact(binaries[0], overrided.Replacements).
		Apply(overrided.NameTemplate)
	if err != nil {
		return err
	}
	var files = map[string]string{}
	for k, v := range overrided.Files {
		files[k] = v
	}
	var log = log.WithField("package", name+"."+format)
	for _, binary := range binaries {
		src := binary.Path
		dst := filepath.Join(ctx.Config.NFPM.Bindir, binary.Name)
		log.WithField("src", src).WithField("dst", dst).Debug("adding binary to package")
		files[src] = dst
	}
	log.WithField("files", files).Debug("all archive files")

File: internal/pipe/snapcraft/snapcraft.go  Lines: 210-221
func push(ctx *context.Context, snap artifact.Artifact) error {
	log.WithField("snap", snap.Name).Info("pushing snap")
	// TODO: customize --release based on snap.Grade?
	/* #nosec */
	var cmd = exec.CommandContext(ctx, "snapcraft", "push", "--release=stable", snap.Path)
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("failed to push %s package: %s", snap.Path, string(out))
	}
	snap.Type = artifact.Snapcraft
	ctx.Artifacts.Add(snap)
	return nil
}

