func (db *DB) UserExists(ctx context.Context) (ExistanceChecker, error) {
	err := permission.LimitCheckAny(ctx)
	if err != nil {
		return nil, err
	}
	m, err := db.userExistMap(ctx)
	if err != nil {
		return nil, err
	}
	return checker(m), nil
}

