func (c *catalog) newPluginConfig(p *ManagedPlugin) (*goplugin.ClientConfig, error) {
	// Build plugin secureConfig struct if a checksum
	// is defined
	var secureConfig *goplugin.SecureConfig
	if p.Config.PluginChecksum != "" {
