+func changedFiles(since string, diffSpec string) []string {
+	if diffSpec != "" {
+		return scm.ChangesIn(diffSpec, "")
+	}
+
+	if since == "" {
+		since = scm.CurrentRevIdentifier()
+	}
+
+	return scm.ChangedFiles(since, true, "")
+}

File: src/query/changed.go  Lines: 15-31
