+				logger.Warningf("get your Goerli ETH and Goerli BZZ now via https://docs.ethswarm.org/docs/installation/fund-your-node")
 			}
 			select {
 			case <-time.After(balanceCheckBackoffDuration):
			case <-timeoutCtx.Done():
