			TaskDefinition: task.TaskDefinitionArn,
		})

		if err != nil {
			return nil, err
		}

		var ci *ecs.ContainerInstance
		var ec2i *ec2.Instance

		for _, i := range dres.ContainerInstances {
			if *i.ContainerInstanceArn == *task.ContainerInstanceArn {
				ci = i
				break
			}
