			oldColumnName := sql.QuoteIdentifier(dff.Old.Name)
			tableName = sql.QuoteIdentifier(tableName)
			cli.Println("ALTER TABLE", tableName, "DROP", oldColumnName, ";")
		case diff.SchDiffColModified:
