func isPublicIP(ip string) bool {
	public, err := regexp.MatchString("(^127\\.)|(^10\\.)|"+
		"(^172\\.1[6-9]\\.)|(^172\\.2[0-9]\\.)|"+
		"(^172\\.3[0-1]\\.)|(^192\\.168\\.)", ip)
	if err != nil {
		log.Error(err)
	}
	return !public
}

