		fmt.Println("Successfully uninstalled.")
	} else {
		return stdcli.Error(fmt.Errorf("Uninstall encountered some errors, contact support@convox.com for assistance"))
	}

	return stdcli.QOSEventSend("cli-uninstall", distinctId, ep)
}

