+func checkHyphens(name string) error {
+	for i := 1; i < len(name); i++ {
+		if name[i-1] == '-' && name[i] == '-' {
+			return errors.New("service name must not contain consecutive hyphens")
+		}
+	}
+	if name[len(name)-1] == '-' {
+		return errors.New("service name must not end in a hyphen")
+	}
+	return nil
+}

