+func (e *ErrorExpr) Validate() error {
+	verr := new(eval.ValidationErrors)
+	rt, ok := e.AttributeExpr.Type.(*ResultTypeExpr)
+	if !ok {
+		return verr
+	}
+	if o := AsObject(rt); o != nil {
+		var errField string
+		for _, n := range *o {
+			if _, ok := n.Attribute.Metadata["error:field"]; ok {
+				if errField != "" {
