func (s *Service) StoreSkipBlock(psbd *StoreSkipBlock) (*StoreSkipBlockReply, error) {
	s.closedMutex.Lock()
	if s.closed {
		s.closedMutex.Unlock()
		return nil, errors.New("closing down")
	}
	s.working.Add(1)
	s.closedMutex.Unlock()
	defer s.working.Done()
