					"Didn't find parent")
			}
			parent.ChildSL = append(parent.ChildSL, prop.Hash)
			changed = append(changed, parent)
		}
		changed = append(changed, prop)
		log.Lvlf3("Propagate %d blocks", len(changed))
		if err := s.startPropagation(changed); err != nil {
