		numGPUs = 0
	case pb.GPUCount_SINGLE_GPU:
		numGPUs = 1
	default:
	}

	return resource.Resources{
		NumCPUs: int(r.inner.GetCPUCores()),
		Memory:  r.inner.GetMaxMemory(),
		NumGPUs: numGPUs,
	}
}

