// Close shuts down the listener
func (h *Host) Close() error {
	time.Sleep(time.Millisecond * 100)
	h.networkLock.Lock()
	var err error
	err = h.host.Close()
	h.connections = make(map[uuid.UUID]network.SecureConn)
	close(h.Closed)
	h.networkLock.Unlock()
	return err
}

