	if ok := rootCertPool.AppendCertsFromPEM(pem); !ok {
		return errors.New("failed to append PEM.")
	}
	cfg := tls.Config{
		RootCAs: rootCertPool,
	}
	if config.TLSCert != "" {
		clientCert := make([]tls.Certificate, 0, 1)

