// GetCPUStatsSet, GetMemoryStatSet, etc.
func (queue *Queue) Reset() {
	queue.lock.Lock()
	defer queue.lock.Unlock()
	for i, _ := range queue.buffer {
		queue.buffer[i].sent = true
	}
