 	spans = append(spans, s) // parent not sampled

+	tp.sampler = AlwaysSample()
 	_, apiSpan = tr.Start(context.Background(), "foo")
 	s = apiSpan.(*span)
 	s.executionTracerTaskEnd = executionTracerTaskEnd
	spans = append(spans, s) // always sample

